// ui/routes/chat/thread-turns.mjs — feature "chat" (docs/chat.md). Generated by tools/split-by-feature.mjs v1;
// the body of register() was moved verbatim from ui/server.mjs. Edit it here from now on.
import { agentIdentity } from '../../../src/core/agent-user.mjs';
import { findPipelineRowById } from '../../../src/core/artifacts.mjs';
import { chatModelRates } from '../../../src/core/ask/chat-price.mjs';
import { validateComposerPayload } from '../../../src/core/ask/composer-payload.mjs';
import { ASK_LIMITS, askLimits as askLimitsFor } from '../../../src/core/ask/limits.mjs';
import { resolveAskMcp, validateMcpOff } from '../../../src/core/ask/mcp.mjs';
import { validateModelEffort } from '../../../src/core/ask/models.mjs';
import { handoffBudgetChars as askHandoffBudgetChars, validateClientContext } from '../../../src/core/ask/prompt.mjs';
import { chatScopeOf, sameScope, scopeBody, withChatScope } from '../../../src/core/ask/scope.mjs';
import { appendMessage as askAppendMessage, getThread as askGetThread, listAttachments as askListAttachments, listMessages as askListMessages, listRunLinks as askListRunLinks, newAskId, setArchived as askSetArchived, switchThreadEngine as askSwitchThreadEngine, updateThread as askUpdateThread } from '../../../src/core/ask/store.mjs';
import { validateAttachmentUploads } from '../../../src/core/attachment-upload.mjs';
import { brokerEngineRefusal } from '../../../src/core/broker-client.mjs';
import { claudeChatSignedOut } from '../../../src/core/claude-auth.mjs';
import { mockEnabled } from '../../../src/core/claude-runner.mjs';
import { budgetStatus } from '../../../src/core/cost-budget.mjs';
import { DIRECTION_MAX_CHARS } from '../../../src/core/directions.mjs';
import { chatDescriptor, chatEngineGate } from '../../../src/core/engines/chat.mjs';
import { flagEnabled } from '../../../src/core/flags.mjs';
import { ASK_ENGINES } from '../../../src/core/model-env.mjs';
import { CLAUDE_SIGNED_OUT_CODE, CLAUDE_SIGNED_OUT_MESSAGE } from '../../../src/core/preflight.mjs';
import { changesCard, landingFacts, landingFactsOfFeature } from '../../../src/core/shape/changes.mjs';
import { isGenericBinary } from '../../../src/shared/artifact-kinds.mjs';
import { chatAttachRefusal, chatSwitchChanges, engineLabel } from '../../../src/shared/engine-switch.mjs';
import { askChatEngine, askChatEngineGate, askContextTokens, askCredentialGate, askDeleting, askEngineSwitchText, askIdParam, askInFlight, askRunningCount, askSignedIn, askSwitchTranscript, askTurnEngine, askViewer, badRequest, broadcast, brokerStartRefusal, factDeps, liveRunEntry, postDirection, startAskTurn, switchThreadScope } from '../../server.mjs';

export function register(app) {

// ---------------------------------------------------------------------------
// #943: an existing chat moves to another engine. Preview (dryRun) → the panel's confirm → commit. Both phases run the
// destination's own checks first, so a refused engine never reaches the confirm, and the commit changes everything in
// ONE transaction, so a refusal leaves the chat as it was.
// ---------------------------------------------------------------------------
const ASK_ENGINE_BUSY = 'wait for this reply to finish before switching the chat\'s engine';

/** The destination's checks before any write, for a model the route already validated: broker policy, the person's
 *  key, then Claude's sign-in (claudeChatSignedOut) or the engine's own turn gate (lockdown, model, cost cap,
 *  binary flags, self-test, sign-in). → {ok:true} | {ok:false, status, error, code, docsUrl?, setupLabel?} */
async function askEnginePreflight({ thread, engine, model, req }) {
  const broker = brokerEngineRefusal(engine);
  if (broker) return { ok: false, status: 409, error: `${engineLabel(engine)}: ${broker}`, code: 'engine-broker' };
  const mock = mockEnabled({});
  if (!mock) {
    const refusal = await brokerStartRefusal(req, [model]);
    if (refusal) return { ok: false, status: 409, error: refusal, code: 'credential-missing' };
  }
  if (engine === 'claude') {
    // As the turn: a relayed chat signs in as its agent user, and an endpoint-routed model at its endpoint.
    if (await claudeChatSignedOut({ model, relay: !!agentIdentity(), mock })) {
      return { ok: false, status: 409, error: CLAUDE_SIGNED_OUT_MESSAGE, code: CLAUDE_SIGNED_OUT_CODE };
    }
    return { ok: true };
  }
  const d = chatDescriptor(engine);
  const limits = askLimitsFor({ projectKey: chatScopeOf(thread.context)?.projectKey || null });
  const gate = await chatEngineGate(d, { model, capped: limits.maxBudgetUsd != null,
    modelPriced: (m) => !!chatModelRates(d, m), mock, relay: !!agentIdentity() });
  if (gate) {
    return { ok: false, status: 409, error: gate.message, code: gate.code || 'engine-refused',
      ...(gate.notReady ? { docsUrl: d.notReady.docsUrl, setupLabel: d.notReady.setupLabel } : {}) };
  }
  return { ok: true };
}

/** What the switch would do, for the confirm: the static changes, both models' context windows, the MCP servers the
 *  destination cannot start, the attachments it cannot view (it gets their names), and the turns its context leaves
 *  out. Writes nothing. */
async function askEngineSwitchPlan(id, thread, { from, to, model, effort }) {
  const [fromTokens, toTokens] = await Promise.all([askContextTokens(thread.model), askContextTokens(model)]);
  const attachments = askListAttachments(id)
    .filter((a) => !isGenericBinary(a))   // a generic file needs no viewing capability: the model gets a name and a path
    .filter((a) => chatAttachRefusal({ engine: to, kind: a.kind, pdf: a.mime === 'application/pdf' }))
    .map((a) => ({ id: a.id, name: a.name }));
  const ctx = thread.context || {};
  const [src, dst] = await Promise.all([
    resolveAskMcp({ ctx, threadId: id, off: thread.mcpOff, model: thread.model, engine: from }),
    resolveAskMcp({ ctx, threadId: id, off: thread.mcpOff, model, engine: to }),
  ]);
  const kept = new Set(((dst.result && dst.result.copies) || []).map((c) => c.name));
  const mcpLost = ((src.result && src.result.copies) || []).filter((c) => !kept.has(c.name)).map((c) => c.copy || c.name);
  return { from, to, model, effort, changes: chatSwitchChanges(from, to), mcpLost, attachments,
    context: { from: fromTokens, to: toTokens },
    transcript: askSwitchTranscript(id, { from, to, budget: askHandoffBudgetChars(toTokens) }) };
}

/** The switch itself: one transaction (store.mjs switchThreadEngine), then the frames every open tab applies. */
function commitAskEngineSwitch(id, { from, to, model, effort, droppedTurns }) {
  const text = askEngineSwitchText(from, to);
  const note = `${engineLabel(to)} starts a fresh session with this chat's transcript as its context${droppedTurns ? `, without the ${droppedTurns} oldest turns` : ''}. Earlier tool calls, cards and runs are not repeated.`;
  const done = askSwitchThreadEngine(id, { engine: to, model, effort, text,
    blocks: [{ kind: 'divider', text, engineSwitch: { from, to, model, effort, droppedTurns } }, { kind: 'notice', text: note }] });
  broadcast({ type: 'ask-message', threadId: id, message: done.message });
  broadcast({ type: 'ask-engine', threadId: id, engine: to, model, effort, threadTotals: done.thread.totals });
  return done;
}

app.post('/api/ask/threads/:id/engine', async (req, res) => {
  const id = askIdParam(res, req.params.id, 'thread');
  if (!id) return;
  try {
    const thread = askGetThread(id);
    if (!thread) return res.status(404).json({ error: 'thread not found' });
    if (req.worcaExtension) return res.status(403).json({ error: 'switch a chat\'s engine in the Worca app', code: 'extension-route' });
    if (thread.mode === 'composer') return badRequest(res, 'a Workflows chat keeps its engine');
    const body = req.body || {};
    if (typeof body.engine !== 'string' || !ASK_ENGINES.includes(body.engine)) return badRequest(res, 'engine must be a chat engine');
    if (body.dryRun !== undefined && typeof body.dryRun !== 'boolean') return badRequest(res, 'dryRun must be true or false');
    if (body.dropTurns !== undefined && !(Number.isInteger(body.dropTurns) && body.dropTurns >= 0)) return badRequest(res, 'dropTurns must be a whole number');
    if (askDeleting.has(id)) return res.status(409).json({ error: 'thread is being deleted' });
    if (askInFlight(id)) return res.status(409).json({ error: ASK_ENGINE_BUSY, code: 'TURN_IN_FLIGHT' });
    const from = askChatEngine(id, thread);
    if (!from) return res.status(409).json({ error: 'this chat has no reply yet: its first message runs on the model you pick', code: 'no-engine-yet' });
    const to = body.engine;
    if (to === from) return badRequest(res, `this chat already runs on ${engineLabel(to)}`);
    const mv = await validateModelEffort(body.model, body.effort, { engine: to });
    // validateModelEffort words a model of another engine for a message ("this chat runs on …"): a switch names its target.
    if (!mv.ok) return badRequest(res, /^this chat runs on /.test(mv.error) ? `${body.model} does not run on ${engineLabel(to)}: pick a model from its section` : mv.error);
    const plan = await askEngineSwitchPlan(id, thread, { from, to, model: mv.model, effort: mv.effort });
    const pre = await askEnginePreflight({ thread, engine: to, model: mv.model, req });
    if (!pre.ok) {
      return res.status(pre.status).json({ error: pre.error, code: pre.code, ...(pre.docsUrl ? { docsUrl: pre.docsUrl, setupLabel: pre.setupLabel } : {}) });
    }
    if (body.dryRun === true) return res.json(plan);
    // From here no await: re-check what the awaits above may have changed, then one transaction.
    if (askDeleting.has(id)) return res.status(409).json({ error: 'thread is being deleted' });
    if (askInFlight(id)) return res.status(409).json({ error: ASK_ENGINE_BUSY, code: 'TURN_IN_FLIGHT' });
    const cur = askGetThread(id);
    if (!cur) return res.status(404).json({ error: 'thread not found' });
    if (askChatEngine(id, cur) !== from) return res.status(409).json({ error: 'this chat changed engine meanwhile: open the model picker again', code: 'engine-changed' });
    // Recounted now, not taken from the plan: a turn that ran during the preflight's awaits can have added rows.
    const dropped = askSwitchTranscript(id, { from, to, budget: askHandoffBudgetChars(plan.context.to) }).droppedTurns;
    if (dropped > 0 && body.dropTurns !== dropped) {
      return res.status(409).json({ error: `${engineLabel(to)} will not see the ${dropped} oldest turns of this chat: confirm that first`, code: 'confirm-dropped-turns', droppedTurns: dropped });
    }
    const done = commitAskEngineSwitch(id, { from, to, model: mv.model, effort: mv.effort, droppedTurns: dropped });
    res.json({ ok: true, thread: done.thread, message: done.message, engineSwitch: { engine: to, model: mv.model, effort: mv.effort } });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.post('/api/ask/threads/:id/messages', async (req, res) => {
  const id = askIdParam(res, req.params.id, 'thread');
  if (!id) return;
  try {
    const thread = askGetThread(id);
    if (!thread) return res.status(404).json({ error: 'thread not found' });
    if (req.worcaExtension && thread.mode === 'composer') return res.status(403).json({ error: 'the browser extension uses Ask threads only', code: 'extension-route' });
    if (askDeleting.has(id)) return res.status(409).json({ error: 'thread is being deleted' });
    if (askInFlight(id)) return res.status(409).json({ error: 'turn in flight' });
    // Budget gate (F6), same figure /api/run enforces: Ask spend is folded into the
    // total window (cost-budget.mjs totalWindowSpendUsd), so chat must stop at
    // the cap it helps fill instead of spending past it while pipelines are 403'd
    // (review of PR #376).
    const budget = budgetStatus();
    if (budget.blocked) return res.status(403).json({ error: 'total cost limit reached', budget });
    if (askRunningCount() >= ASK_LIMITS.turnsGlobal) {
      return res.status(429).json({ error: `at most ${ASK_LIMITS.turnsGlobal} turns may run at once` });
    }
    const body = req.body || {};
    const text = typeof body.text === 'string' ? body.text : '';
    if (!text.trim()) return badRequest(res, 'text is required');
    // The credential broker keeps Claude keys only: a Codex chat would spend codex's own sign-in, shared by everyone and
    // readable by the agent. Refused before the model check, which no longer lists Codex rows.
    const engineGate = askChatEngineGate(id, thread);
    if (engineGate) return res.status(engineGate.status).json({ error: engineGate.error, code: engineGate.code });
    const mv = await validateModelEffort(body.model, body.effort, { engine: askChatEngine(id, thread) });
    if (!mv.ok) return badRequest(res, mv.error);
    const credGate = await askCredentialGate(req, body.model);
    if (credGate) return res.status(credGate.status).json({ error: credGate.error, code: credGate.code });
    const cv = validateClientContext(body.context);
    if (!cv.ok) return badRequest(res, cv.error);
    // MCP registry §9.4: the composer sends the picker's choices with every message; they decide this turn and are stored.
    const mo = body.mcpOff === undefined ? { ok: true, value: undefined } : validateMcpOff(body.mcpOff);
    if (!mo.ok) return badRequest(res, mo.error);
    if (body.agentMode !== undefined && typeof body.agentMode !== 'boolean') return badRequest(res, 'agentMode must be true or false');
    // Workflows view (D11): a composer chat sends the open canvas with EVERY message. It is validated here and
    // stored on the thread before the turn, so the MCP child and the prompt read what the user sees now.
    let composerState = null;
    if (thread.mode === 'composer') {
      // Attachments ride a composer message exactly as an Ask one: validated below (before any write), then stored,
      // inlined and listed by startAskTurn, whose prompt path is the same for both modes.
      const pc = validateComposerPayload(body.composer);
      if (!pc.ok) return badRequest(res, pc.error);
      composerState = pc.value;
    }
    // P4 (CONTRACT §4): the chat scope this message runs in. A context carrying `pinned` is authoritative — the scope
    // pill sent it (false = No project: no page target rides along). A context without it (a pre-#397 tab, an API
    // caller) keeps the thread's stored scope, else the projectKey / workspaceId it names; a projectDir never does.
    const scope = cv.context.pinned === undefined ? (chatScopeOf(thread.context) || chatScopeOf(cv.context)) : chatScopeOf(cv.context);
    const ctx = withChatScope(cv.context, scope);

    // §7.3 — validate EVERY attachment before ANY write (all-or-nothing), through the validation the Requirements page
    // shares (src/core/attachment-upload.mjs): Ask's caps, its engine refusals and its messages. The engine is read per
    // file, as before; the objects handed on are Ask's own shapes (no hash is made, no raw bytes for a text kind).
    const files = [];
    if (body.attachments !== undefined) {
      const v = validateAttachmentUploads(body.attachments, {
        maxFiles: ASK_LIMITS.attachment.maxFiles, maxBytesPerFile: ASK_LIMITS.attachment.maxBytesPerFile,
        maxBytesPerBinaryFile: ASK_LIMITS.attachment.maxBytesPerBinaryFile, maxBytesTotal: ASK_LIMITS.attachment.maxBytesPerMessage,
        hash: false,
        refuse: (cls, name) => {
          // Runs for a LISTED extension only (an unlisted one needs no viewing capability).
          // D16: what the chat's engine cannot take (a Codex chat no PDF; Copilot, Gemini CLI and Qwen Code no image or
          // PDF) is refused at attach time, before any write. (classifyExtension gives kind text|image|binary; a PDF is
          // kind 'binary', mime 'application/pdf'.)
          const attachRefused = chatAttachRefusal({ engine: askTurnEngine(id, thread, mv.model), kind: cls.kind, pdf: cls.mime === 'application/pdf' });
          return attachRefused ? `${attachRefused}: ${name}` : null;
        },
      });
      if (!v.ok) return res.status(v.status).json({ error: v.error });
      for (const f of v.files) {
        files.push(f.kind === 'text'
          ? { name: f.name, kind: 'text', mime: f.mime, text: f.text, bytes: f.bytes }
          : { name: f.name, kind: f.kind, mime: f.mime, data: f.data, bytes: f.bytes });
      }
    }

    // P4: a send that changes the chat scope (a pick the PATCH refused mid-turn, a second tab, an API caller's first
    // message) switches first, so every tab's pill follows; a chat with messages gets the divider before the user row.
    if (!sameScope(chatScopeOf(thread.context), scope)) {
      try { await switchThreadScope(id, scopeBody(scope), { divider: askListMessages(id).length > 0 }); }
      catch (err) { if (err.code === 'TURN_IN_FLIGHT') return res.status(409).json({ error: 'turn in flight' }); throw err; }
    }
    if (composerState) askUpdateThread(id, { composer: composerState });
    if (thread.archivedAt) askSetArchived(id, false);   // #948 s2: a message brings an archived chat back
    const r = await startAskTurn({ threadId: id, thread, ctx, model: mv.model, effort: mv.effort, text, files, signedIn: askSignedIn(req), reader: askViewer(req), mcpOff: mo.value, agentMode: body.agentMode, client: req.worcaExtension ? 'browser-extension' : null });
    if (!r.ok) return res.status(r.status).json({ error: r.error, ...(r.code ? { code: r.code } : {}), ...(r.budget ? { budget: r.budget } : {}) });
    // `attachments` carries the store-minted ids so the sender's own echo can key
    // image thumbnails and the thread budget off them (the ask-message broadcast
    // may have raced ahead of this response, or been missed on a brand-new thread).
    res.status(202).json({
      userMessageId: r.userMessageId, assistantMessageId: r.assistantMessageId, attachments: r.attachments,
      // the thread's context chips after this turn's merge, so the header repaints without a re-fetch
      contexts: askGetThread(id)?.contexts ?? [],
    });
  } catch (err) {
    // startAskTurn never throws (it returns {ok:false,…}); only the route's own
    // pre-checks can land here, so there is no slot to release.
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// Idempotent stop (the /api/agents/generate/stop family): always {ok:true}
// after the shape check; the costUsd:null rule lives in the turn (R-C).
app.post('/api/ask/threads/:id/stop', (req, res) => {
  const id = askIdParam(res, req.params.id, 'thread');
  if (!id) return;
  if (req.worcaExtension && askGetThread(id)?.mode === 'composer') return res.status(403).json({ error: 'the browser extension uses Ask threads only', code: 'extension-route' });
  const job = askInFlight(id);
  if (job && job.turn && typeof job.turn.stop === 'function') {
    try { job.turn.stop(); } catch { /* best-effort */ }
  }
  res.json({ ok: true });
});
/** A turn of this thread is still being written (askInFlight: the job while it runs). */
const threadTurnBusy = (threadId) => askInFlight(threadId) != null;
/** The person's message and an assistant row carrying the card, both broadcast (offerShipCard's way). → the assistant row */
function postThreadExchange(threadId, text, card) {
  const user = askAppendMessage(threadId, { role: 'user', text, blocks: [] });
  broadcast({ type: 'ask-message', threadId, message: user });
  const message = askAppendMessage(threadId, { role: 'assistant', text: '', status: 'done',
    blocks: [{ kind: 'card', id: newAskId('card'), state: 'proposed', card }] });
  broadcast({ type: 'ask-message', threadId, message });
  return message;
}

// Shaper s5 (D5): Ask for changes from a finished card. body { pipelineId? | featureId?, text } → 201 { message }
app.post('/api/ask/threads/:id/changes', async (req, res) => {
  try {
    const id = askIdParam(res, req.params.id, 'thread');
    if (!id) return;
    const { pipelineId, featureId, text } = req.body || {};
    if (typeof text !== 'string' || !text.trim()) return badRequest(res, 'text is required');
    if (text.length > 4000) return badRequest(res, 'text must be at most 4000 characters');
    if (!askGetThread(id)) return res.status(404).json({ error: 'thread not found' });
    if (threadTurnBusy(id)) return res.status(409).json({ error: 'a reply is still being written' });
    const facts = typeof featureId === 'string' && featureId ? landingFactsOfFeature(featureId, factDeps)
      : landingFacts(String(pipelineId || ''), factDeps);
    if (facts && facts.run && facts.run.finished === false) return res.status(409).json({ error: 'the run is still going' });
    const halted = facts && facts.feature && facts.feature.slices.find((s) => ['stopped', 'error', 'failed', 'paused'].includes(s.state));
    if (halted) return res.status(409).json({ error: `Run ${halted.index} stopped: resume or re-plan it first` });
    const card = facts && changesCard({ text, facts, requirementsOn: flagEnabled('shapeRequirements') });
    if (!card) return res.status(409).json({ error: 'this run has no single branch to change' });
    const message = postThreadExchange(id, text.trim(), card);
    res.status(201).json({ message });
  } catch (err) {
    if (!res.headersSent) res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// Chat P3 (R10): a direction from the chat composer's "→ run" chip. The run must be one this thread follows
// (ask_run_links: by its run_id — a live UUID, or the 8-hex id track_run stores — or its pipeline_id). The text goes
// through the SAME in-process post as POST /api/runs/:id/directions; then the thread keeps it as a user row carrying
// a `direction` block, plus a system notice, both broadcast like the follower's notices (no model turn, no cost).
// A refusal appends nothing.
app.post('/api/ask/threads/:id/directions', async (req, res) => {
  const id = askIdParam(res, req.params.id, 'thread');
  if (!id) return;
  const { runId, text } = req.body || {};
  if (typeof runId !== 'string' || !runId) return badRequest(res, 'runId is required');
  if (text === undefined || text === null || text === '') return badRequest(res, 'text is required');
  if (typeof text !== 'string') return badRequest(res, 'text must be a string');
  if (!text.trim()) return badRequest(res, 'text is required');
  if (text.length > DIRECTION_MAX_CHARS) return badRequest(res, `text must be at most ${DIRECTION_MAX_CHARS} characters`);
  try {
    if (!askGetThread(id)) return res.status(404).json({ error: 'thread not found' });
    if (askDeleting.has(id)) return res.status(409).json({ error: 'thread is being deleted' });
    const links = askListRunLinks(id);
    // A proposal launch links the live UUID and learns the pipeline id from the follower's first `state`; the chip names
    // the run by its pipeline id, so a link not (yet) filled in matches through its live entry.
    const link = links.find((l) => l.runId === runId || l.pipelineId === runId)
      || links.find((l) => !l.pipelineId && (liveRunEntry(l.runId) || {}).pipelineId === runId) || null;
    if (!link) return res.status(404).json({ error: 'this chat does not follow that run' });
    const entry = liveRunEntry(link.runId) || (link.pipelineId ? liveRunEntry(link.pipelineId) : null);
    const pipelineId = link.pipelineId || (entry && entry.pipelineId) || (/^[0-9a-f]{8}$/.test(link.runId) ? link.runId : null);
    if (!pipelineId) return res.status(409).json({ error: 'the run has not started yet', code: 'NOT_STARTED' });
    const body = text.trim();
    const rec = await postDirection(pipelineId, body, 'chat');        // directions.mjs source: 'ui' | 'cli' | 'chat…'
    if (!rec) return res.status(404).json({ error: 'pipeline not found' });
    const row = findPipelineRowById(pipelineId);
    const title = (row && row.title) || (entry && entry.title) || 'run';
    // The row text carries the label: the bubble reads "Direction to #<id>: …", and a restored session
    // (buildRestoredPrompt replays user rows as "User: <text>") never mistakes it for a question to Ask.
    const label = `Direction to #${pipelineId}`;
    // The run HAS the direction now: a thread write that fails (the chat deleted mid-post, a busy DB) must not come back
    // as an error the chip shows as "Not sent" — a resend would post it to the run twice.
    let message = null, notice = null;
    try {
      message = askAppendMessage(id, { role: 'user', text: `${label}: ${body}`,
        blocks: [{ kind: 'direction', id: rec.id, runId: link.runId, pipelineId, title, label }] });
      broadcast({ type: 'ask-message', threadId: id, message });
      const noticeText = `Direction sent to “${title}” · the next step reads it`;
      notice = askAppendMessage(id, { role: 'system', text: noticeText, blocks: [{ kind: 'notice', text: noticeText }] });
      broadcast({ type: 'ask-message', threadId: id, message: notice });
    } catch (err) {
      console.error(`[worca-ui] direction ${rec.id} reached the run but not the chat: ${err && err.message ? err.message : err}`);
    }
    res.status(201).json({ id: rec.id, message, notice });
  } catch (err) {
    if (err && err.code === 'RUN_FINISHED') return res.status(409).json({ error: err.message, code: 'RUN_FINISHED' });
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});
}
